import 'package:cloud_firestore/cloud_firestore.dart';
class UnifiedSearchService { final FirebaseFirestore db; UnifiedSearchService({FirebaseFirestore? firestore}):db=firestore??FirebaseFirestore.instance; Future<QuerySnapshot<Map<String,dynamic>>> users(String q,{int limit=25})=>db.collection('users').orderBy('usernameLower').startAt([q.toLowerCase()]).endAt([q.toLowerCase()+'\\uf8ff']).limit(limit).get(); Future<QuerySnapshot<Map<String,dynamic>>> messages(String chat,{int limit=200})=>db.collection('chats').doc(chat).collection('messages').orderBy('timestamp',descending:true).limit(limit).get(); }